// Assessment order is independent within each subject. No line joins different subjects.
export const trendColors=['#187d87','#b35b2b','#6854a3','#3179b6','#a84370','#657c28','#997320','#456cb0','#8b5760','#2f8b68','#885b9b','#926132','#32676d','#4256ad','#6275a2','#768e36','#9c508a','#3b808c','#9b6d35','#546f85'];
export function buildSubjectTrends(entries,subjects=[]){
 const names=[...new Set([...subjects,...entries.map(e=>e.subject)])].sort(),series=[];
 for(const subject of names){const rows=entries.filter(e=>e.subject===subject).slice().sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title)||a.assessmentId.localeCompare(b.assessmentId));const seen=new Set(),unique=rows.filter(e=>{if(seen.has(e.assessmentId))return false;seen.add(e.assessmentId);return true;});const points=unique.map((entry,index)=>({...entry,assessmentOrder:index+1})).filter(e=>typeof e.percentage==='number'&&Number.isFinite(e.percentage));if(points.length)series.push({subject,color:trendColors[names.indexOf(subject)%trendColors.length],assessmentCount:unique.length,points});}
 return{series,maxAssessments:Math.max(1,...series.map(s=>s.assessmentCount))};
}
export function renderSubjectTrend(entries,{subjects=[],selectedSubject='',esc,pct}){
 const model=buildSubjectTrends(entries,subjects),selected=model.series.find(s=>s.subject===selectedSubject),visible=selected?[selected]:model.series,max=Math.max(1,...visible.map(s=>s.assessmentCount));
 if(!model.series.length)return '<section class="panel"><div class="empty">No saved marks in this view. Choose another subject or date range.</div></section>';
 const x=order=>max===1?310:45+(order-1)*535/(max-1),y=percentage=>145-percentage*1.3,coordinates=points=>points.map(p=>x(p.assessmentOrder)+','+y(p.percentage)).join(' '),single=visible.length===1;
 const ticks=[...new Set([1,...Array.from({length:Math.min(max,6)},(_,i)=>Math.round(1+i*(max-1)/Math.max(1,Math.min(max,6)-1))),max])];
 return `<section class="panel subject-trend-panel"><div class="panel-head"><div><h2>Assessment trend</h2><p>Each line follows one subject’s assessments, oldest → newest.</p></div></div><div class="trend-subject-controls" role="group" aria-label="Subjects shown in assessment trend"><button class="trend-subject-choice ${selected?'':'selected'}" data-action="grades-trend-subject" data-subject="" aria-pressed="${!selected}">All subjects</button>${model.series.map(series=>`<button class="trend-subject-choice ${selected?.subject===series.subject?'selected':''}" data-action="grades-trend-subject" data-subject="${esc(series.subject)}" aria-pressed="${selected?.subject===series.subject}" title="Show only ${esc(series.subject)}"><svg viewBox="0 0 12 12" aria-hidden="true"><circle cx="6" cy="6" r="4" fill="${series.color}"/></svg>${esc(series.subject)}</button>`).join('')}</div><div class="trend-chart"><svg viewBox="0 0 600 190" role="img" aria-label="Separate assessment trend lines by subject; assessment order within each subject on the horizontal axis and percentage on the vertical axis">${[0,50,100].map(v=>`<line x1="40" y1="${y(v)}" x2="585" y2="${y(v)}" class="chart-grid"/><text x="0" y="${y(v)+4}">${v}%</text>`).join('')}${ticks.map(order=>`<text x="${x(order)}" y="163" text-anchor="middle">${order}</text>`).join('')}${visible.map(series=>{const classPoints=series.points.filter(p=>typeof p.classAverage==='number'&&Number.isFinite(p.classAverage));return `<g data-trend-subject="${esc(series.subject)}">${single&&classPoints.length?`<polyline class="subject-class-trend" stroke="${series.color}" points="${classPoints.map(p=>x(p.assessmentOrder)+','+y(p.classAverage)).join(' ')}"/>${classPoints.map(p=>`<circle class="subject-class-point" stroke="${series.color}" cx="${x(p.assessmentOrder)}" cy="${y(p.classAverage)}" r="3"><title>${esc(series.subject+' · Assessment '+p.assessmentOrder+' · '+p.title+' · Class average '+pct(p.classAverage))}</title></circle>`).join('')}`:''}<polyline class="subject-student-trend" stroke="${series.color}" points="${coordinates(series.points)}"/>${series.points.map(p=>`<a href="#/assessment?id=${encodeURIComponent(p.assessmentId)}&student=${encodeURIComponent(p.studentId)}" aria-label="${esc(series.subject+' assessment '+p.assessmentOrder+': '+p.title+', '+pct(p.percentage))}"><circle class="subject-student-point" fill="${series.color}" cx="${x(p.assessmentOrder)}" cy="${y(p.percentage)}" r="4.5"><title>${esc(series.subject+' · Assessment '+p.assessmentOrder+' · '+p.date+' · '+p.title+': '+pct(p.percentage)+'; class '+pct(p.classAverage))}</title></circle></a>`).join('')}</g>`;}).join('')}<text x="310" y="185" text-anchor="middle">Assessment order within each subject</text></svg><p class="trend-explanation">${single?'Solid line: student · Dashed line: class average for the same subject.':'Select a subject above to see it on its own, with its matching class averages.'} ${visible.some(s=>s.points.length===1)?'A subject with one marked assessment shows one point.':''} Missed assessments have no plotted score.</p></div></section>`;
}
